// The export arrives as flat rows. The workbook wants both the rows and a
// per-region roll-up, so the aggregation happens here rather than in Excel.
const src = $('Set your company and template').first().json;

const rows = src.rows_in.map((r) => {
  const units = Number(r.units);
  const unitPrice = Number(r.unit_price);
  return {
    region: r.region,
    rep: r.rep,
    channel: r.channel || 'Direct',
    units,
    unit_price: unitPrice,
    revenue: Math.round(units * unitPrice * 100) / 100,
    prior_revenue: Number(r.prior_revenue || 0),
  };
});

const byRegion = new Map();
for (const r of rows) {
  const g = byRegion.get(r.region) || { name: r.region, reps: [], units: 0, revenue: 0, prior_revenue: 0 };
  if (!g.reps.includes(r.rep)) g.reps.push(r.rep);
  g.units += r.units;
  g.revenue = Math.round((g.revenue + r.revenue) * 100) / 100;
  g.prior_revenue = Math.round((g.prior_revenue + r.prior_revenue) * 100) / 100;
  byRegion.set(r.region, g);
}
const regions = [...byRegion.values()].sort((a, b) => b.revenue - a.revenue);

return [{
  json: {
    template_name: src.template_name,
    company: src.company,
    currency: src.currency,
    source: src.source,
    period: src.period,
    generated: new Date().toISOString().slice(0, 10),
    rows,
    regions,
  },
}];
